import { describe, expect, it } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { validateSpec } from './validate.js';

const here = path.dirname(fileURLToPath(import.meta.url));

function fullSpec(overrides: Partial<Record<string, string>> = {}): string {
  const sections: Record<string, string> = {
    tier: `### 5.1 Risk tier

- **Tier**: limited
- **Justification**: Chatbot answering policy questions; no automated decisions about people.
- **Sign-off**: not required (tier below high)`,
    data: `### 5.2 Data provenance & privacy

- **Data sources**: internal policy docs; user questions at runtime
- **PII involved?**: no
- **Retention**: prompts kept 30 days, then hard-deleted
- **Used for training?**: no; provider training disabled`,
    oversight: `### 5.3 Human oversight

- **Automation level**: assistive
- **Override path**: support team can correct answers via admin panel
- **Kill switch**: feature flag chat_enabled, ops on-call, off within 5 minutes`,
    evaluation: `### 5.4 Evaluation plan

- **Pre-ship metrics & thresholds**: groundedness >= 0.85; refusal rate <= 2%
- **Eval dataset**: eval/policy-qa.jsonl, 300 questions from real support tickets
- **Who runs it and when**: CI on every prompt change`,
    bias: `### 5.5 Bias & fairness

- **Groups at risk of disparate impact**: non-native English speakers
- **Mitigations**: multilingual eval slice; simplified-language prompt rule
- **How tested**: disaggregated groundedness by question language`,
    monitoring: `### 5.6 Monitoring & rollback

- **Production monitoring**: thumbs-down rate, refusal rate, latency
- **Degradation definition**: thumbs-down > 10% over 24h
- **Rollback trigger & procedure**: on-call flips chat_enabled off; users see the legacy FAQ`,
    transparency: `### 5.7 Transparency & incident response

- **User disclosure**: "AI assistant" label in the chat header
- **Incident owner**: Dana Rivers (support-eng rotation)
- **Incident path**: in-chat report -> triage queue -> fix or disable, response within 24h`
  };
  Object.assign(sections, overrides);
  return `# Spec: Policy Chatbot

## 1. Objective

Answer policy questions.

## 5. Responsible AI Gate

${Object.values(sections).join('\n\n')}

## 6. Rollout

Later.`;
}

describe('validateSpec', () => {
  it('blocks a spec with no gate section', () => {
    const result = validateSpec('# Spec\n\n## Objective\n\nBuild a thing.');
    expect(result.verdict).toBe('BLOCK');
    expect(result.findings[0].checkId).toBe('structure');
  });

  it('passes a fully answered gate', () => {
    const result = validateSpec(fullSpec());
    expect(result.findings).toEqual([]);
    expect(result.verdict).toBe('PASS');
    expect(result.tier).toBe('limited');
  });

  it('blocks the untouched template (empty fields)', () => {
    const template = fs.readFileSync(
      path.join(here, '../../assets/rai-spec-template.md'),
      'utf8'
    );
    const result = validateSpec(template);
    expect(result.verdict).toBe('BLOCK');
    expect(result.findings.some((f) => f.message.includes('Unanswered field'))).toBe(true);
  });

  it('blocks placeholder answers', () => {
    const result = validateSpec(
      fullSpec({
        data: `### 5.2 Data provenance & privacy

- **Data sources**: TBD
- **PII involved?**: no
- **Retention**: 30 days
- **Used for training?**: no`
      })
    );
    expect(result.verdict).toBe('BLOCK');
    expect(result.findings.some((f) => f.checkId === 'data-privacy')).toBe(true);
  });

  it('blocks a missing subsection', () => {
    const spec = fullSpec();
    const withoutBias = spec.replace(/### 5\.5 Bias & fairness[\s\S]*?(?=### 5\.6)/, '');
    const result = validateSpec(withoutBias);
    expect(result.verdict).toBe('BLOCK');
    expect(result.findings.some((f) => f.checkId === 'bias' && f.message.includes('Missing'))).toBe(
      true
    );
  });

  it('blocks high risk without sign-off', () => {
    const result = validateSpec(
      fullSpec({
        tier: `### 5.1 Risk tier

- **Tier**: high
- **Justification**: Screens job applications automatically.
- **Sign-off**: not required (tier below high)`
      })
    );
    expect(result.verdict).toBe('BLOCK');
    expect(result.findings.some((f) => f.message.includes('sign-off'))).toBe(true);
  });

  it('accepts high risk with a named sign-off', () => {
    const result = validateSpec(
      fullSpec({
        tier: `### 5.1 Risk tier

- **Tier**: high
- **Justification**: Screens job applications automatically.
- **Sign-off**: Ana Pop (Head of Compliance), 2026-08-01`
      })
    );
    expect(result.findings.filter((f) => f.checkId === 'risk-tier')).toEqual([]);
  });

  it('blocks a prohibited tier', () => {
    const result = validateSpec(
      fullSpec({
        tier: `### 5.1 Risk tier

- **Tier**: prohibited
- **Justification**: Social scoring.
- **Sign-off**: n/a`
      })
    );
    expect(result.verdict).toBe('BLOCK');
    expect(result.findings.some((f) => f.message.includes('must not be built'))).toBe(true);
  });

  it('blocks an unrecognized tier value', () => {
    const result = validateSpec(
      fullSpec({
        tier: `### 5.1 Risk tier

- **Tier**: medium-ish
- **Justification**: Feels fine.
- **Sign-off**: not required (tier below high)`
      })
    );
    expect(result.verdict).toBe('BLOCK');
    expect(result.tier).toBeNull();
  });

  it('accepts the branded "## FRAI Gate" heading', () => {
    const spec = fullSpec().replace('## 5. Responsible AI Gate', '## FRAI Gate');
    const result = validateSpec(spec);
    expect(result.verdict).toBe('PASS');
    expect(result.tier).toBe('limited');
  });

  it('warns when the evaluation plan has no numbers', () => {
    const result = validateSpec(
      fullSpec({
        evaluation: `### 5.4 Evaluation plan

- **Pre-ship metrics & thresholds**: we will check answers look good
- **Eval dataset**: some real questions
- **Who runs it and when**: the team, before release`
      })
    );
    expect(result.verdict).toBe('WARN');
    expect(
      result.findings.some((f) => f.checkId === 'evaluation' && f.severity === 'warn')
    ).toBe(true);
  });
});
#!/usr/bin/env node
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { validateSpec } from './gate/validate.js';
import { renderJson, renderText } from './gate/report.js';
import { verdictFrom } from './gate/schema.js';
import { draftGateSection, smartReview } from './pipeline/agent.js';

const TEMPLATE_PATH = fileURLToPath(new URL('../assets/rai-spec-template.md', import.meta.url));

const CI_WORKFLOW = `name: Responsible AI Gate
on:
  pull_request:
  push:
    branches: [main]
jobs:
  rai-gate:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: '20'
      # Blocks the build until every Responsible AI Gate check in the spec is answered.
      - run: npx frai-gate check FRAI-SPEC.md
`;

const HELP = `frai-gate - the FRAI Gate: a Responsible AI Gate for specs

Usage:
  frai-gate init [--out <file>] [--ci]   Drop the RAI spec template into the repo (default: FRAI-SPEC.md);
                                         --ci also writes .github/workflows/rai-gate.yml so the gate
                                         runs on every PR
  frai-gate check <spec.md> [options]    Validate the spec's Responsible AI Gate
      --smart                            Add an AI quality review of the gate answers (Claude Agent SDK)
      --json                             Machine-readable output
  frai-gate draft [--out <file>] [--print]
                                         Scan this repo with a read-only agent and draft a filled-in
                                         gate section grounded in the code (default out: rai-gate-draft.md)

Exit codes: 0 = PASS/WARN, 1 = BLOCK, 2 = usage/error.
The smart commands (draft, check --smart) use the Claude Agent SDK and need Claude Code
authentication or ANTHROPIC_API_KEY. Model override: FRAI_GATE_MODEL (default claude-opus-5).`;

interface Args {
  command: string | undefined;
  positional: string[];
  flags: Map<string, string | true>;
}

function parseArgs(argv: string[]): Args {
  const [command, ...rest] = argv;
  const positional: string[] = [];
  const flags = new Map<string, string | true>();
  for (let i = 0; i < rest.length; i += 1) {
    const arg = rest[i];
    if (arg.startsWith('--')) {
      const name = arg.slice(2);
      const next = rest[i + 1];
      if (next !== undefined && !next.startsWith('--') && ['out', 'spec'].includes(name)) {
        flags.set(name, next);
        i += 1;
      } else {
        flags.set(name, true);
      }
    } else {
      positional.push(arg);
    }
  }
  return { command, positional, flags };
}

async function cmdInit(args: Args): Promise<number> {
  const out = typeof args.flags.get('out') === 'string' ? (args.flags.get('out') as string) : 'FRAI-SPEC.md';
  const target = path.resolve(process.cwd(), out);
  try {
    await fs.access(target);
    console.error(`Refusing to overwrite existing file: ${out}`);
    return 2;
  } catch {
    // does not exist - good
  }
  const template = await fs.readFile(TEMPLATE_PATH, 'utf8');
  await fs.writeFile(target, template);
  console.log(`Created ${out}. Fill in every FRAI Gate field, then run: frai-gate check ${out}`);
  if (args.flags.has('ci')) {
    const wfDir = path.resolve(process.cwd(), '.github/workflows');
    const wfPath = path.join(wfDir, 'rai-gate.yml');
    try {
      await fs.access(wfPath);
      console.error('Skipping CI workflow: .github/workflows/rai-gate.yml already exists.');
    } catch {
      await fs.mkdir(wfDir, { recursive: true });
      const workflow =
        out === 'FRAI-SPEC.md' ? CI_WORKFLOW : CI_WORKFLOW.replace('FRAI-SPEC.md', out);
      await fs.writeFile(wfPath, workflow);
      console.log('Created .github/workflows/rai-gate.yml - the gate now runs on every PR.');
    }
  }
  return 0;
}

async function cmdCheck(args: Args): Promise<number> {
  const specPath = args.positional[0];
  if (!specPath) {
    console.error('Usage: frai-gate check <spec.md> [--smart] [--json]');
    return 2;
  }
  const markdown = await fs.readFile(path.resolve(process.cwd(), specPath), 'utf8');
  const result = validateSpec(markdown);

  if (args.flags.has('smart') && result.gateSection) {
    const agentFindings = await smartReview(markdown, process.cwd());
    result.findings.push(...agentFindings);
    result.verdict = verdictFrom(result.findings);
  } else if (args.flags.has('smart') && !result.gateSection) {
    console.error('Skipping smart review: no gate section to review.');
  }

  console.log(args.flags.has('json') ? renderJson(result, specPath) : renderText(result, specPath));
  return result.verdict === 'BLOCK' ? 1 : 0;
}

async function cmdDraft(args: Args): Promise<number> {
  const section = await draftGateSection(process.cwd());
  if (args.flags.has('print')) {
    console.log(section);
    return 0;
  }
  const out = typeof args.flags.get('out') === 'string' ? (args.flags.get('out') as string) : 'rai-gate-draft.md';
  await fs.writeFile(path.resolve(process.cwd(), out), `${section}\n`);
  console.log(`Drafted gate section written to ${out}.`);
  console.log('Review it, resolve every "NEEDS HUMAN INPUT" item, paste it into your spec, then run: frai-gate check <spec.md>');
  return 0;
}

async function main(): Promise<void> {
  const args = parseArgs(process.argv.slice(2));
  let code = 0;
  switch (args.command) {
    case 'init':
      code = await cmdInit(args);
      break;
    case 'check':
      code = await cmdCheck(args);
      break;
    case 'draft':
      code = await cmdDraft(args);
      break;
    case undefined:
    case 'help':
    case '--help':
      console.log(HELP);
      break;
    default:
      console.error(`Unknown command: ${args.command}\n`);
      console.log(HELP);
      code = 2;
  }
  process.exitCode = code;
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 2;
});
import { Finding, GateResult } from './schema.js';

const VERDICT_ICON: Record<GateResult['verdict'], string> = {
  PASS: '✅',
  WARN: '⚠️',
  BLOCK: '⛔'
};

function line(finding: Finding): string {
  const icon = finding.severity === 'block' ? '⛔' : '⚠️';
  const tag = finding.source === 'agent' ? ' (smart review)' : '';
  return `${icon} [${finding.checkId}]${tag} ${finding.message}`;
}

export function renderText(result: GateResult, specPath: string): string {
  const out: string[] = [];
  out.push(`FRAI Gate - ${specPath}`);
  out.push(`Verdict: ${VERDICT_ICON[result.verdict]} ${result.verdict}`);
  if (result.tier) out.push(`Risk tier: ${result.tier}`);
  if (result.findings.length === 0) {
    out.push('All seven gate checks answered. Clear to implement.');
  } else {
    out.push('');
    for (const finding of result.findings) out.push(line(finding));
    out.push('');
    if (result.verdict === 'BLOCK') {
      out.push('BLOCK: fix the items above before implementation starts.');
    } else if (result.verdict === 'WARN') {
      out.push('WARN: the gate passes structurally, but tighten the flagged answers.');
    }
  }
  return out.join('\n');
}

export function renderJson(result: GateResult, specPath: string): string {
  return JSON.stringify(
    {
      spec: specPath,
      verdict: result.verdict,
      tier: result.tier,
      findings: result.findings
    },
    null,
    2
  );
}

