  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function tiersIn(text: string): RiskTier[] {
  // Skip the template's enum hint "(prohibited / high / limited / minimal)".
  const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
  return RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
}

function extractTier(body: string): RiskTier | null {
  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const lines = body.split(/\r?\n/);
  const fieldIndex = lines.findIndex(
    (l) => /\*\*\s*(risk\s+)?tier\s*:?\s*\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l)
  );
  if (fieldIndex === -1) {
    const found = tiersIn(body);
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      // Ambiguous mention; prefer the value after a colon.
      const inValue = tiersIn(body.split(':').slice(1).join(':'));
      if (inValue.length === 1) return inValue[0];
    }
    return null;
  }
  const fieldLine = lines[fieldIndex];
  const nested = nestedLines(lines, fieldIndex);
  // The first candidate naming exactly one tier wins: the field line, its value after the colon,
  // then the answer indented below it (as a whole, then line by line).
  const candidates = [
    fieldLine,
    fieldLine.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '').split(':').slice(1).join(':'),
    [fieldLine, ...nested].join('\n'),
    ...nested
  ];
  for (const text of candidates) {
    const found = tiersIn(text);
    if (found.length === 1) return found[0];
  }
  return null;
}

/** The sign-off value: the Sign-off field's inline value plus any answer indented below it. */
function extractSignoff(body: string): string {
  const lines = body.split(/\r?\n/);
  const label = (l: string) => l.match(FIELD_LINE)?.[2] ?? '';
  let index = lines.findIndex((l) => /sign[- ]?off/i.test(label(l)));
  if (index === -1) {
    index = lines.findIndex((l, i) => /sign[- ]?off/i.test(l) && !isUnansweredField(lines, i));
  }
  if (index === -1 || isUnansweredField(lines, index)) return '';
  return [inlineValue(lines[index]), ...nestedLines(lines, index).map((l) => l.trim())]
    .join('\n')
    .trim();
}

function unansweredFields(body: string): string[] {
  const lines = body.split(/\r?\n/);
  return lines.filter((_, i) => isUnansweredField(lines, i));
}

function answeredText(body: string): string {
  const lines = body.split(/\r?\n/);
  return lines
    .filter((_, i) => !isUnansweredField(lines, i))
    .join('\n')
    .trim();
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
    });
    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
  }

  const subsections = splitSubsections(gateSection);
  let tier: RiskTier | null = null;

  for (const check of GATE_CHECKS) {
    const section = subsections.find((s) => check.headingPattern.test(s.heading));
    if (!section) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Missing gate subsection: "${check.title}".`,
        source: 'validator'
      });
      continue;
    }

    const body = section.body;
    const answered = answeredText(body);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    const emptyFields = body.split(/\r?\n/).filter((l) => EMPTY_FIELD.test(l));
    for (const line of emptyFields) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${line.trim()}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const signoffLine = body
          .split(/\r?\n/)
          .find((l) => /sign[- ]?off/i.test(l) && !EMPTY_FIELD.test(l));
        const signoffValue = signoffLine ? signoffLine.split(':').slice(1).join(':').trim() : '';
        if (!signoffValue || /not\s+required/i.test(signoffValue)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}

