import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
/** The marker `frai-gate draft` leaves where only a human can answer. */
const NEEDS_HUMAN_INPUT = /\bNEEDS HUMAN INPUT\b/g;
/** A bulleted field line: `- **Retention**: 30 days` or `- **Retention:** 30 days`. */
const FIELD_LINE = /^(\s*)[-*]\s*\*\*([^*]+)\*\*(.*)$/;

interface Section {
  heading: string;
  body: string;
}

function indentOf(line: string): number {
  const lead = line.match(/^\s*/)?.[0] ?? '';
  return lead.replace(/\t/g, '    ').length;
}

/** Non-blank lines indented below line `index` (blank lines in between are allowed). */
function nestedLines(lines: string[], index: number): string[] {
  const base = indentOf(lines[index]);
  const nested: string[] = [];
  for (let i = index + 1; i < lines.length; i += 1) {
    if (!lines[i].trim()) continue;
    if (indentOf(lines[i]) <= base) break;
    nested.push(lines[i]);
  }
  return nested;
}

/** Skips a leading "(hint ...)" (parentheses may nest) and returns the rest, or null when unbalanced. */
function skipParenthetical(text: string): string | null {
  let depth = 0;
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === '(') depth += 1;
    else if (text[i] === ')') depth -= 1;
    if (depth === 0) return text.slice(i + 1);
  }
  return null;
}

/** The value written on a field line itself, after the label, its hint, and the colon. */
function inlineValue(line: string): string {
  const m = line.match(FIELD_LINE);
  if (!m) return line.split(':').slice(1).join(':').trim();
  let rest = m[3];
  if (m[2].trim().endsWith(':')) return rest.trim();
  if (rest.trim().startsWith('(')) rest = skipParenthetical(rest.trim()) ?? rest;
  const colon = rest.match(/^\s*:(.*)$/);
  return (colon ? colon[1] : rest).trim();
}

/**
 * A field line with no answer: nothing after the label (`- **Retention:**`), or a line ending
 * in a colon (`- **Retention** (how long):`), and no indented answer below it.
 */
function isUnansweredField(lines: string[], index: number): boolean {
  const m = lines[index].match(FIELD_LINE);
  if (!m) return false;
  const boldColonEmpty = m[2].trim().endsWith(':') && !m[3].trim();
  if (!boldColonEmpty && !/:\s*$/.test(lines[index])) return false;
  return nestedLines(lines, index).every((l) => isUnansweredField([l], 0));
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function tiersIn(text: string): RiskTier[] {
  // Skip the template's enum hint "(prohibited / high / limited / minimal)".
  const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
  return RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
}

function extractTier(body: string): RiskTier | null {
  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const lines = body.split(/\r?\n/);
  const fieldIndex = lines.findIndex(
    (l) => /\*\*\s*(risk\s+)?tier\s*:?\s*\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l)
  );
  if (fieldIndex === -1) {
    const found = tiersIn(body);
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      // Ambiguous mention; prefer the value after a colon.
      const inValue = tiersIn(body.split(':').slice(1).join(':'));
      if (inValue.length === 1) return inValue[0];
    }
    return null;
  }
  const fieldLine = lines[fieldIndex];
  const nested = nestedLines(lines, fieldIndex);
  // The first candidate naming exactly one tier wins: the field line, its value after the colon,
  // then the answer indented below it (as a whole, then line by line).
  const candidates = [
    fieldLine,
    fieldLine.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '').split(':').slice(1).join(':'),
    [fieldLine, ...nested].join('\n'),
    ...nested
  ];
  for (const text of candidates) {
    const found = tiersIn(text);
    if (found.length === 1) return found[0];
  }
  return null;
}

/** The sign-off value: the Sign-off field's inline value plus any answer indented below it. */
function extractSignoff(body: string): string {
  const lines = body.split(/\r?\n/);
  const label = (l: string) => l.match(FIELD_LINE)?.[2] ?? '';
  let index = lines.findIndex((l) => /sign[- ]?off/i.test(label(l)));
  if (index === -1) {
    index = lines.findIndex((l, i) => /sign[- ]?off/i.test(l) && !isUnansweredField(lines, i));
  }
  if (index === -1 || isUnansweredField(lines, index)) return '';
  return [inlineValue(lines[index]), ...nestedLines(lines, index).map((l) => l.trim())]
    .join('\n')
    .trim();
}

function unansweredFields(body: string): string[] {
  const lines = body.split(/\r?\n/);
  return lines.filter((_, i) => isUnansweredField(lines, i));
}

function answeredText(body: string): string {
  const lines = body.split(/\r?\n/);
  return lines
    .filter((_, i) => !isUnansweredField(lines, i))
    .join('\n')
    .trim();
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
    });
    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
  }

  const subsections = splitSubsections(gateSection);
  let tier: RiskTier | null = null;

  for (const check of GATE_CHECKS) {
    const section = subsections.find((s) => check.headingPattern.test(s.heading));
    if (!section) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Missing gate subsection: "${check.title}".`,
        source: 'validator'
      });
      continue;
    }

    const body = section.body;
    const answered = answeredText(body);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    const humanInputs = body.match(NEEDS_HUMAN_INPUT)?.length ?? 0;
    if (humanInputs > 0) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" has ${humanInputs} unresolved "NEEDS HUMAN INPUT" item${humanInputs === 1 ? '' : 's'}. Answer ${humanInputs === 1 ? 'it' : 'them'} and remove the marker.`,
        source: 'validator'
      });
    }
    for (const line of unansweredFields(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${line.trim()}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
